const p = $('Pedido: preparar').first().json;
let t = String($input.first().json.candidates?.[0]?.content?.parts?.map((x) => x.text || '').join('') || '').trim();
t = t.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^["“]|["”]$/g, '').trim();
if (p.tipo === 'orcamento_cabelo') {
  // valor é da a dona: se o texto perdeu ou inventou algum número, manda as palavras dela
  const numeros = (s) => String(s).match(/\d+(?:[.,]\d+)*/g) || [];
  const dela = numeros(p.resposta), permitidos = dela.concat(numeros(p.pergunta));
  if (!t || !dela.every((n) => numeros(t).includes(n)) || !numeros(t).every((n) => permitidos.includes(n))) t = ('A ' + $('Loja').first().json.dona + ' passou o orçamento: ') + p.resposta;
}
if (!t) t = ('Falei com a ' + $('Loja').first().json.dona + ' sobre isso: ') + p.resposta;
