// lista do Redis: [0] = mais nova (a memória grava com LPUSH)
const lista = [].concat($input.first().json.memoria || []);
const quebra = (s) => { try { const m = JSON.parse(s); return m.type === 'tool' || (m.type === 'ai' && (m.data?.tool_calls || []).length > 0); } catch (e) { return false; } };
let fim = Math.min(lista.length, 40);
if (!fim || !quebra(lista[fim - 1])) return [{ json: { cortar: false }, pairedItem: 0 }];
// recua até uma mensagem dela: o histórico começa como uma conversa normal
const dela = (s) => { try { return JSON.parse(s).type === 'human'; } catch (e) { return false; } };
while (fim > 0 && !dela(lista[fim - 1])) fim--;
// toda interação começa com a mensagem dela, então sempre há um ponto bom; sem ele, não mexe
if (!fim) return [{ json: { cortar: false }, pairedItem: 0 }];
return [{ json: { cortar: true, de: lista.length, para: fim, manter: lista.slice(0, fim) }, pairedItem: 0 }];

// memória: [0] = mais nova (LPUSH). Uma interação = mensagem dela (human) + resposta (ai, e ferramentas)
const lista = [].concat($('Descarte: memória ler').first().json.memoria || []);
const baloes = $('Quebrar mensagens').all().map((i) => i.json.texto);
const atual = $('Um balão por vez').first().json.texto;
const saiu = Math.max(0, baloes.indexOf(atual));
const tipo = (s) => { try { return JSON.parse(s).type; } catch (e) { return ''; } };
let manter = lista;
let devolver = [];
if (saiu === 0) {
  // nada chegou nela: esta interação sai da memória e as mensagens dela voltam para a fila
  const i = lista.findIndex((s) => tipo(s) === 'human');
  if (i >= 0) manter = lista.slice(i + 1);
  try { devolver = JSON.parse($('Montar entrada').first().json.mensagens || '[]'); } catch (e) { devolver = []; }
} else if (tipo(lista[0]) === 'ai') {
  // parte chegou: a memória fica só com os balões que ela recebeu
  const m = JSON.parse(lista[0]);
  m.data = Object.assign({}, m.data, { content: baloes.slice(0, saiu).join('\n\n') });
  manter = [JSON.stringify(m)].concat(lista.slice(1));
}
const precoVolta = baloes.slice(saiu).some((b) => /R\$\s?\d|\b\d{2,}(?:\.\d{3})*(?:,\d{2})?\s*reais\b/i.test(String(b || '')));
return [{ json: { precoVolta, saiu, mexer: lista.length > 0 && manter !== lista, manter, devolver }, pairedItem: 0 }];

// lê o JSON do Gemini; qualquer coisa fora do esperado = não guarda
const VALOR = /R\$\s?\d|\b\d{2,}(?:\.\d{3})*(?:,\d{2})?\s*reais\b/i;
