const L = $('Loja').first().json;
if (L.conversa_barrada) {
  const sem9 = (n) => { const d = String(n).replace(/\D/g, ''); return /^55\d{2}9\d{8}$/.test(d) ? d.slice(0, 4) + d.slice(5) : d; };
  const k = ($("Webhook Evolution").first().json.body.data || {}).key || {};
